"""Kibana Agent Builder MCP tools as custom Python tools (generated by ../build_projects.py).

Managed `define_mcp` cannot send a static `Authorization: ApiKey` header, so each tool calls the Kibana
MCP endpoint itself over streamable HTTP (plain httpx: no dependency on a particular `mcp` package
version). KIBANA_MCP_URL and ES_API_KEY are read from deployment secrets at call time.
"""
import json
import os

import httpx
from langchain_core.tools import StructuredTool

